// === Tab: mySketch ===
// for the BirdsNest Streaming Backgrounds @sableRaph (eg #WCCChallenge) <3

var SZE = 35;
var PAL = [
	[0, 255],	[0, 255],	[0, 255],
	["darkred", "navy"],
	["orange", "lime"]
];
var CLRS;

function setup() {
	createCanvas(SZE*(windowWidth/SZE-2), SZE*(windowHeight/SZE-2));
	describe("stripes altered with difference blocks");
	frameRate(2)
	CLRS = random(PAL);
	noStroke();
	fill(CLRS[1]);
}

function draw() {
	blendModebackground(CLRS[0]);

	// stripes
	for (let y = 0; y < height; y += SZE) {
		for (let x = (-(frameCount)%4)*SZE; x < width; x += 4 * SZE) {
			rect(x, y, SZE + SZE, SZE);
		}		
	}

	blendMode(DIFFERENCE)
	// grid
	for (let x = (-(frameCount)%4+1)*SZE; x < width; x += 2 * SZE) {
		for (let y = ~~random(2.75) * SZE; y < height; y += ~~random(3, 5.5) * SZE) {
			rect(x, y, SZE + SZE, SZE);
		}		
	}
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}
